- (void)viewDidLoad {
 [super viewDidLoad]; self.view.backgroundColor=[UIColor colorWithRed:.035 green:.039 blue:.055 alpha:1]; self.navigationController.navigationBarHidden=YES;
 UIView *card=[UIView new]; card.backgroundColor=[UIColor colorWithRed:.075 green:.082 blue:.12 alpha:1]; card.layer.cornerRadius=24; card.translatesAutoresizingMaskIntoConstraints=NO;
 self.eyebrowLabel=[UILabel new]; self.eyebrowLabel.text=@"SLEEP STORE"; self.eyebrowLabel.textColor=[UIColor colorWithRed:.62 green:.52 blue:1 alpha:1]; self.eyebrowLabel.font=[UIFont systemFontOfSize:11 weight:UIFontWeightSemibold]; self.eyebrowLabel.translatesAutoresizingMaskIntoConstraints=NO;
 UILabel *title=[UILabel new]; title.text=@"Ativar dispositivo"; title.textColor=UIColor.whiteColor; title.font=[UIFont systemFontOfSize:28 weight:UIFontWeightBold]; title.translatesAutoresizingMaskIntoConstraints=NO;
 self.messageLabel=[UILabel new]; self.messageLabel.text=@"Insira sua key para vincular este dispositivo com segurança."; self.messageLabel.textColor=[UIColor colorWithWhite:.7 alpha:1]; self.messageLabel.numberOfLines=0; self.messageLabel.translatesAutoresizingMaskIntoConstraints=NO;
 self.codeField=[UITextField new]; self.codeField.placeholder=@"Insira sua key"; self.codeField.textColor=UIColor.whiteColor; self.codeField.font=[UIFont monospacedSystemFontOfSize:16 weight:UIFontWeightMedium]; self.codeField.backgroundColor=[UIColor colorWithWhite:0 alpha:.28]; self.codeField.layer.cornerRadius=14; self.codeField.translatesAutoresizingMaskIntoConstraints=NO;
 self.continueButton=[UIButton buttonWithType:UIButtonTypeSystem]; [self.continueButton setTitle:@"Ativar dispositivo" forState:UIControlStateNormal]; [self.continueButton setTitleColor:UIColor.whiteColor forState:UIControlStateNormal]; self.continueButton.backgroundColor=[UIColor colorWithRed:.4 green:.28 blue:.95 alpha:1]; self.continueButton.layer.cornerRadius=14; self.continueButton.translatesAutoresizingMaskIntoConstraints=NO; [self.continueButton addTarget:self action:@selector(activate:) forControlEvents:UIControlEventTouchUpInside];
 UIButton *discord=[UIButton buttonWithType:UIButtonTypeSystem]; [discord setTitle:@"Discord · @sleepff" forState:UIControlStateNormal]; [discord setTitleColor:[UIColor colorWithRed:.62 green:.52 blue:1 alpha:1] forState:UIControlStateNormal]; discord.translatesAutoresizingMaskIntoConstraints=NO; [discord addTarget:self action:@selector(openDiscord:) forControlEvents:UIControlEventTouchUpInside];
