 [NSLayoutConstraint activateConstraints:@[[card.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor constant:20],[card.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor constant:-20],[card.centerYAnchor constraintEqualToAnchor:self.view.centerYAnchor],[self.eyebrowLabel.leadingAnchor constraintEqualToAnchor:card.leadingAnchor constant:24],[self.eyebrowLabel.topAnchor constraintEqualToAnchor:card.topAnchor constant:26],[title.leadingAnchor constraintEqualToAnchor:card.leadingAnchor constant:24],[title.topAnchor constraintEqualToAnchor:self.eyebrowLabel.bottomAnchor constant:8],[self.messageLabel.leadingAnchor constraintEqualToAnchor:card.leadingAnchor constant:24],[self.messageLabel.trailingAnchor constraintEqualToAnchor:card.trailingAnchor constant:-24],[self.messageLabel.topAnchor constraintEqualToAnchor:title.bottomAnchor constant:10],[self.codeField.leadingAnchor constraintEqualToAnchor:card.leadingAnchor constant:24],[self.codeField.trailingAnchor constraintEqualToAnchor:card.trailingAnchor constant:-24],[self.codeField.topAnchor constraintEqualToAnchor:self.messageLabel.bottomAnchor constant:24],[self.codeField.heightAnchor constraintEqualToConstant:54],[self.continueButton.leadingAnchor constraintEqualToAnchor:card.leadingAnchor constant:24],[self.continueButton.trailingAnchor constraintEqualToAnchor:card.trailingAnchor constant:-24],[self.continueButton.topAnchor constraintEqualToAnchor:self.codeField.bottomAnchor constant:14],[self.continueButton.heightAnchor constraintEqualToConstant:52],[discord.topAnchor constraintEqualToAnchor:self.continueButton.bottomAnchor constant:8],[discord.centerXAnchor constraintEqualToAnchor:card.centerXAnchor],[discord.bottomAnchor constraintEqualToAnchor:card.bottomAnchor constant:-14]]]; [self ensureDeviceKey]; [self validateStoredToken];
