- (void)openDiscord:(id)sender { [[UIApplication sharedApplication] openURL:[NSURL URLWithString:@"https://discord.gg/sleepff"] options:@{} completionHandler:nil]; }
- (void)ensureDeviceKey { NSData *tag=[KeychainTag dataUsingEncoding:NSUTF8StringEncoding]; NSDictionary *q=@{(__bridge id)kSecClass:(__bridge id)kSecClassKey,(__bridge id)kSecAttrApplicationTag:tag,(__bridge id)kSecReturnRef:@YES}; if(SecItemCopyMatching((__bridge CFDictionaryRef)q,(CFTypeRef *)&_privateKey)!=errSecSuccess){ NSDictionary *a=@{(__bridge id)kSecAttrKeyType:(__bridge id)kSecAttrKeyTypeECSECPrimeRandom,(__bridge id)kSecAttrKeySizeInBits:@256,(__bridge id)kSecPrivateKeyAttrs:@{(__bridge id)kSecAttrIsPermanent:@YES,(__bridge id)kSecAttrApplicationTag:tag}}; _privateKey=SecKeyCreateRandomKey((__bridge CFDictionaryRef)a,NULL); } }
- (NSString *)publicKeyPEM { SecKeyRef p=SecKeyCopyPublicKey(self.privateKey); CFDataRef d=SecKeyCopyExternalRepresentation(p,NULL); if(p)CFRelease(p); if(!d)return nil; NSString *b64=[(__bridge NSData *)d base64EncodedStringWithOptions:0]; CFRelease(d); return [NSString stringWithFormat:@"-----BEGIN PUBLIC KEY-----\n%@\n-----END PUBLIC KEY-----",b64]; }
- (void)postJSON:(NSDictionary *)body path:(NSString *)path completion:(void (^)(NSDictionary *,NSError *))completion { NSMutableURLRequest *r=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:[API_BASE_URL stringByAppendingString:path]]]; r.HTTPMethod=@"POST"; [r setValue:@"application/json" forHTTPHeaderField:@"Content-Type"]; r.HTTPBody=[NSJSONSerialization dataWithJSONObject:body options:0 error:nil]; [[[NSURLSession sharedSession] dataTaskWithRequest:r completionHandler:^(NSData *d,NSURLResponse *res,NSError *e){ NSDictionary *j=d?[NSJSONSerialization JSONObjectWithData:d options:0 error:nil]:@{}; dispatch_async(dispatch_get_main_queue(),^{completion(j,e);}); }] resume]; }
- (void)validateStoredToken { NSDictionary *q=@{(__bridge id)kSecClass:(__bridge id)kSecClassGenericPassword,(__bridge id)kSecAttrAccount:KeychainToken,(__bridge id)kSecReturnData:@YES}; CFTypeRef ref=NULL; if(SecItemCopyMatching((__bridge CFDictionaryRef)q,&ref)!=errSecSuccess)return; NSString *code=[[NSString alloc] initWithData:CFBridgingRelease(ref) encoding:NSUTF8StringEncoding]; [self postJSON:@{@"key":code, @"installationId":[self publicKeyPEM]?:@""} path:@"/api/license/validate" completion:^(NSDictionary *j,NSError *e){if(!e&&[j[@"status"] isEqual:@"active"]) [self dismissViewControllerAnimated:NO completion:nil];}]; }
- (void)activate:(id)sender { NSString *code=[self.codeField.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet]; NSString *pub=[self publicKeyPEM]; if(!code.length||!pub.length){self.messageLabel.text=@"Informe uma key válida.";return;} [self postJSON:@{@"key":code,@"installationId":pub} path:@"/api/license/activate" completion:^(NSDictionary *j,NSError *e){if(!e&&[j[@"status"] isEqual:@"active"]){NSData *d=[code dataUsingEncoding:NSUTF8StringEncoding]; NSDictionary *i=@{(__bridge id)kSecClass:(__bridge id)kSecClassGenericPassword,(__bridge id)kSecAttrAccount:KeychainToken,(__bridge id)kSecValueData:d}; SecItemAdd((__bridge CFDictionaryRef)i,NULL); [self dismissViewControllerAnimated:YES completion:nil];}else self.messageLabel.text=@"Key inválida ou inexistente.";}]; }
